CREATE TABLE livestock_health_records(`id` bigint  UNSIGNED PRIMARY KEY AUTO_INCREMENT,`created_at` timestamp  DEFAULT CURRENT_TIMESTAMP NOT NULL,`updated_at` timestamp  DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP NOT NULL,`enable` TINYINT(1)  NOT NULL  DEFAULT 1 ,`livestock_id` bigint  NOT NULL,`record_type` varchar(255)  NOT NULL COMMENT 'vaccination, checkup, treatment, breeding',`record_date` date  NOT NULL,`description` text  NOT NULL,`veterinarian_name` varchar(255)  NULL,`cost` DECIMAL(10,2)  NULL,`next_due_date` date  NULL COMMENT 'For vaccinations and checkups',`notes` text  NULL)ENGINE = InnoDB AUTO_INCREMENT = 1 DEFAULT CHARSET = utf8;